@spec tracker_page_spec  src=tests/specs/tracker_page_spec.lua  loc=1698  cases=53
@exercises tuning (tuning), configManager (h.cm), commandManager (h.cmgr), midiManager (h.mm), trackerManager (h.tm)
@surface   tuning.derive, tuning.genDiamond, cm:setContext, cmgr:push, cmgr:invoke, cm:getAt, cm:set, cm:get, tuning.stepToMidi, mm:subscribe, mm:notes, tm:assignEvent, tm:byUuid, tm:flush
@harness   mk, reaper:addItem, reaper:setProjectTracks, reaper:seedMidi

# Intent
  Pin-tests for trackerPage's Page interface (bind / unbind / focusState /
  bind-from-cursor) and the retune modal's slots, defaults and dispatch.
  render / handleInput are stubs wired in step 3 and verified in REAPER, not here.

# Helpers
  @fn resetArrange()  @ 59-177
  @fn seedItems(h, takes, srcLen)  @ 193-198
      -- A bind re-keys cm's track tier off the take's own item, so a take named in
      -- fakeArrange needs one in the fake project too.
  @fn newTrackerPage(cm, ds, cmgr, chrome, gui)  @ 200-209
  @fn trackList(trackCount)  @ 211-217
  @fn mapTracker(harness, inst, trackCount)  @ 222-236
      -- A tracker bound to the take 'i0' over a track list of the given width, with
      -- i0's placement as the caller states it; inst = nil binds it into no instance.
      -- Returns the page's tv, and the harness behind it for the cmgr.

# Cases
  @case 'bind(take) drives cm:setContext via the page's own tm:bindTake'  [harness]  @ 240-248
  @case 'unbind() drives cm:setContext(nil) via the page's own tm:bindTake'  [harness]  @ 251-260
  @case 'focusState before any render returns both bits false'  [harness]  @ 263-270
  @case 'bindFromSelection binds tm to the resolved selection take, drops when the track has no slots'  [harness]  @ 276-289
  @case 'with no live instance, the new take mints a parked slot and selects it'  [harness]  @ 293-310
  @case 'deleteBoundSlot confirms, then deletes the bound slot through the arrange facade'  [harness]  @ 316-337
  @case 'take properties renames the bound take\'s slot, not that one take'  [harness]  @ 343-361
  @case 'take properties follows the bound take when the tracker sits on another slot'  [harness]  @ 368-386
  @case 'the new take places below the current instance and becomes current'  [harness]  @ 392-425
  @case 'a new take on a just-selected track parks, rather than appending on the old one'  [harness]  @ 429-453
  @case 'duplicate below appends another instance of the bound slot and makes it current'  [harness]  @ 459-489
  @case 'duplicate below refuses where the free span falls short'  [harness]  @ 493-514
  @case 'duplicate below on a slot whose only take is parked does nothing'  [harness]  @ 518-531
  @case 'the variant step rebinds the tracker to the slot stepped to and follows its placement'  [harness]  @ 537-571
  @case 'a variant step with the tracker in no instance does nothing'  [harness]  @ 575-589
  @case 'prev/next track + take drive the tv selection, not the arrange cursor'  [harness]  @ 593-616
  @case 'a track step lands on the placement overlapping the current instance most'  [harness]  @ 620-656
  @case 'with nothing overlapping, a track step lands on the placement nearest in time'  [harness]  @ 660-695
  @case 'F6 plays from the instance dived into, not the placement the bind resolved'  [harness]  @ 702-719
  @case 'a dive outranks a play head already sitting in another instance'  [harness]  @ 723-746
  @case 'the play head entering an instance makes it current; leaving one writes nothing'  [harness]  @ 750-773
  @case 'a slot change seeks from the outgoing instance, backwards for prevTake'  [harness]  @ 777-812
  @case 'the walk steps along the track's placements in start order, holding at the ends'  [harness]  @ 816-864
  @case 'a walk into another slot resets the caret; within one slot the caret holds'  [harness]  @ 868-905
  @case 'deleting the instance drops that placement and lands on the one before it'  [harness]  @ 909-943
  @case 'a slot with no live instance leaves the tracker nowhere, and F6 silent'  [harness]  @ 947-963
  @case 'the map window centres the bound column, and clamps it at both ends'  [harness]  @ 972-990
  @case 'the map window pages time, a start in the last bar opening the next page'  [harness]  @ 994-1010
  @case 'with the tracker in no instance the map window pages on the edit cursor'  [harness]  @ 1014-1021
  @case 'the map window carries the takes over it, the current instance marked'  [harness]  @ 1025-1036
  @case 'the map window carries the transport it meets, and only that'  [harness]  @ 1040-1063
  @case 'the map loop candidate snaps to the cell, widens to one, and holds at 0'  [harness]  @ 1067-1086
  @case 'the map drives the transport, and a hand-set loop drops loop to item'  [harness]  @ 1090-1101
  @case 'the pin key holds the map up as the palette default, and drops it when pressed again'  [harness]  @ 1105-1114
  @case 'a gesture raises the map, and it falls at the next command'  [harness]  @ 1118-1159
  @case 'the play row is the head\'s offset into the current instance, in rows'  [harness]  @ 1163-1190
  @case 'the play row dims where the head is sounding a sibling instance'  [harness]  @ 1194-1218
  @case 'the cut row is where the rendered span stops short of the source'  [harness]  @ 1225-1246
  @case 'the play row and the head row count from the source origin, not the start'  [harness]  @ 1252-1276
  @case 'a dive carries the arrange QN to the caret row, and the caret hands it back'  [harness]  @ 1283-1302
  @case 'a caret outside the rendered span hands back the row the span stops at'  [harness]  @ 1306-1325
  @case 'leaving the tracker puts the arrange caret where the tracker caret is'  [harness]  @ 1329-1351
  @case 'with loop to item on, a dive brackets the instance dived into'  [harness]  @ 1357-1375
  @case 'the play head entering an instance leaves the loop where it was'  [harness]  @ 1379-1397
  @case 'the toggle command brackets the current instance as it comes on'  [harness]  @ 1401-1423
  @case 'Esc clears the loop and drops loop to item with it'  [harness]  @ 1427-1438
  @case 'the loop-to-item verb brackets the current instance, toggle or no toggle'  [harness]  @ 1442-1466
  @case 'retune opens on the scope the selection implies and OK snaps that scope'  [harness]  @ 1472-1527
  @case 'retune opens on the facility the take carries, its dials on their figures'  [harness]  @ 1535-1564
  @case 'a refused retune offers to widen, and the offer taken solves again'  [harness]  @ 1570-1613
  @case 'empty grid shows the single no-takes message'  [harness]  @ 1619-1633
  @case 'an owned tm flush resyncs the watcher baseline; only a foreign write trips the reload'  [harness]  @ 1640-1672
  @case 'bindFromSelection re-keys cm on return from dormancy even when the take is unchanged'  [harness]  @ 1676-1696

